INSERT INTO public."community_rules" ("id", "code", "name", "description", "is_active", "created_at") VALUES (1, 'SPAM', 'สแปมหรือโฆษณาไม่พึงประสงค์', 'เนื้อหาซ้ำซ้อน ขายของผิดที่ โฆษณาเว็บพนันหรือสแปมลิงก์', TRUE, '2026-10-25T10:26:17.716632+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."community_rules" ("id", "code", "name", "description", "is_active", "created_at") VALUES (2, 'HARASSMENT', 'การคุกคามหรือกลั่นแกล้ง', 'การใช้ถ้อยคำดูถูก ข่มขู่ หรือล้อเลียนผู้อื่นให้เสียหาย', TRUE, '2026-10-25T10:26:17.716632+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."community_rules" ("id", "code", "name", "description", "is_active", "created_at") VALUES (3, 'INAPPROPRIATE', 'เนื้อหาไม่เหมาะสมหรือไม่เกี่ยวข้องกับอาหาร', 'รูปภาพลามกอนาจาร รูปภาพที่ไม่เกี่ยวกับอาหาร หรือคำหยาบคาย', TRUE, '2026-10-25T10:26:17.716632+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."community_rules" ("id", "code", "name", "description", "is_active", "created_at") VALUES (4, 'COPYRIGHT', 'การละเมิดลิขสิทธิ์', 'คัดลอกรูปภาพหรือเนื้อหาที่มีลิขสิทธิ์โดยไม่ได้รับอนุญาต', TRUE, '2026-10-25T10:26:17.716632+00:00') ON CONFLICT DO NOTHING;
